mark = int(input())

if mark >= 90:
    grade = "A"
elif mark >= 75:
    grade = "B"
elif mark >= 60:
    grade = "C"
elif mark >= 40:
    grade = "D"
else:
    grade = "F"

print(f"Grade: {grade}")

pin_valid = int(input())
account_balance = int(input())
withdrawal_amount = int(input())

if pin_valid == 1:
    if withdrawal_amount <= 0:
        print("Error: Invalid Amount")
    elif withdrawal_amount > account_balance:
        print("Error: Insufficient Balance")
    elif withdrawal_amount > 10000:
        print("Error: Exceeds Daily Limit")
    else:
        account_balance -= withdrawal_amount
        print(f"Success: Dispensed ₹{withdrawal_amount}, Balance: ₹{account_balance}")
else:
    print("Error: Invalid PIN")

units = int(input())

if units <= 100:
    bill = 0
elif units <= 200:
    bill = (units - 100) * 2
elif units <= 400:
    bill = (100 * 2) + (units - 200) * 4
else:
    bill = (100 * 2) + (200 * 4) + (units - 400) * 6

print(f"Total Bill: ₹{bill}")
